window.openCreateRegionModal=function(){const e=document.getElementById("createRegionModal");e&&(e.classList.add("open"),document.body.style.overflow="hidden")};window.openEditRegionModal=function(e,t,o,n,i,d,a){const l=document.getElementById("editRegionModal"),c=document.getElementById("editRegionForm");if(!l||!c)return;c.action=`/regionales/${e}`,document.getElementById("editRegionName").value=t,document.getElementById("editRegionCode").value=o,document.getElementById("editRegionDepartment").value=n,document.getElementById("editRegionManager").value=i==="—"?"":i,document.getElementById("editRegionAddress").value=d==="—"?"":d;const m=document.getElementById("editRegionStatus");m&&(m.value=a||"Operativo"),l.classList.add("open"),document.body.style.overflow="hidden"};window.deleteRegion=function(e,t){if(typeof window.metricConfirm=="function")window.metricConfirm({title:"¿Eliminar Sede Regional?",text:`¿Estás seguro de eliminar la sede regional ${t}?`,icon:"warning",confirmText:"Sí, eliminar",cancelText:"Cancelar",isDanger:!0}).then(o=>{if(o.isConfirmed){const n=document.getElementById("deleteFormGlobal");n&&(n.action=`/regionales/${e}`,n.submit())}});else if(confirm(`¿Eliminar la sede ${t}?`)){const o=document.getElementById("deleteFormGlobal");o&&(o.action=`/regionales/${e}`,o.submit())}};window.closeModal=function(e){const t=document.getElementById(e);t&&(t.classList.remove("open"),document.body.style.overflow="")};window.filterRegionsLive=function(){const e=document.getElementById("regionsSearchInput");if(!e)return;const t=e.value.toLowerCase().trim();document.querySelectorAll("#regionsMasterTable tbody tr").forEach(n=>{const i=n.textContent.toLowerCase();n.style.display=i.includes(t)?"":"none"})};
